          'register-parental': { title: 'Register parental leave', steps: ['Open Manager Panel and click "Register parental leave" next to "Grant Vacation/Day Off".', 'Choose the employee, the start date and the end date (the last day of parental leave), and optionally write a note.', 'Click "Register parental leave". It is approved at once and needs no application.'], notes: 'The end date can be corrected later with "Edit" in the vacation overview, where the type can be switched between vacation and parental leave. The employee is notified that parental leave has been registered.' },
