          'read-message': { title: 'Lue viestisi', steps: ['Avaa Sähköpostijärjestelmä.', 'Valitse "Sähköposti" saapuneille viesteille tai "Lähetetty" itse lähettämillesi viesteille.', 'Avaa viesti napsauttamalla sitä.'] },
