          'read-message': { title: 'Läs dina meddelanden', steps: ['Öppna E-postsystem.', 'Välj "Inkorg" för mottagna meddelanden eller "Skickat" för dem du själv har skickat.', 'Klicka på ett meddelande för att öppna det.'] },
