          'list-views': { title: 'Se pågående, genomförda och avvisade förslag', steps: ['Öppna Förbättringar och förslag. Listan visar som standard de pågående förslagen.', 'Klicka på "Genomförda" för att se de avslutade förslagen, eller "Avvisade" för de som har avvisats.', 'Klicka på "Pågående" för att gå tillbaka till de aktiva förslagen.'] },
          'answer-invitation': { title: 'Svara på en inbjudan till ett förslag', steps: ['Öppna förslaget under "Förbättringar och förslag".', 'Klicka på "Godkänn inbjudan" eller "Avböj inbjudan".'] },
          'finish-improvement': { title: 'Markera en förbättring som klar', steps: ['Öppna förslaget som ansvarig.', 'Klicka på "Markera som klart (för godkännande)". En chef godkänner därefter avslutet.'] },
          'unseen-changes': { title: 'Vad den blå pricken vid ett förslag betyder', steps: ['Ett förslag som rör dig och har ändringar du inte har sett har en blå prick i listan. Pekar du på pricken står det "Nya ändringar som du inte har sett".', 'Öppna förslaget. Då räknas ändringarna som sedda, och pricken försvinner.'] },
